function getWarehouse(id) {
  return FREIGHT_WAREHOUSES.find((w) => w.id === id) || null;
}

// ---------- Product catalog & order-based weight estimate ----------
// A user-maintained catalog of products (dimensions in cm, weight in kg)
// so a quote can start from "how many of each did the customer order"
// instead of the ops team hand-computing a shipment weight every time.
let productSeq = 0;
function newProductId() {
  productSeq += 1;
  return `prod_${Date.now().toString(36)}_${productSeq}`;
}

function defaultProductCatalog() {
  const rows = [
    ["Essential Starter Kit", 31, 15, 27, 1.8],
    ["Essential Refills (30ct)", 13, 15, 10.5, 0.5],
    ["Essential Trial Pack (7ct)", 11, 15, 2.5, 0.1],
    ["Beckham Stack Starter Kit", 43, 15, 27, 2.4],
    ["Longevity Starter Kit", 28, 17, 11.5, 1.42],
    ["Longevity Refills (30ct)", 13, 15, 6, 0.3],
    ["Longevity Trial Pack (7ct)", 11, 15, 2.5, 0.1],
  ];
  return rows.map(([name, lengthCm, widthCm, heightCm, weightKg]) => ({
    id: newProductId(), name, lengthCm, widthCm, heightCm, weightKg,
  }));
}

function emptyProduct() {
  return { id: newProductId(), name: "New product", lengthCm: 0, widthCm: 0, heightCm: 0, weightKg: 0 };
}

// Industry-standard volumetric divisor for an unknown/unpacked shipment
// estimate (cm³ / 5000 = kg) — distinct from a rate card's own dimDivisor,
// which applies once real outer-carton dimensions are known instead (see
// resolveShipmentWeight() below).
const CATALOG_VOLUMETRIC_DIVISOR_CM3_PER_KG = 5000;

// quantities: { [productId]: qty }. Ignores products with qty <= 0 (or
// not present). Returns the actual/volumetric/chargeable estimate implied
// by the catalog alone — before any real outer-carton override.
function computeOrderWeights(products, quantities) {
  quantities = quantities || {};
  let totalActualKg = 0;
  let totalVolumeCm3 = 0;
  const lines = [];
  for (const p of products) {
    const qty = Number(quantities[p.id]) || 0;
    if (qty <= 0) continue;
    const lineWeightKg = qty * (Number(p.weightKg) || 0);
    const lineVolumeCm3 = qty * (Number(p.lengthCm) || 0) * (Number(p.widthCm) || 0) * (Number(p.heightCm) || 0);
    totalActualKg += lineWeightKg;
    totalVolumeCm3 += lineVolumeCm3;
    lines.push({ productId: p.id, name: p.name, qty, lineWeightKg, lineVolumeCm3 });
  }
  const volumetricKg = totalVolumeCm3 / CATALOG_VOLUMETRIC_DIVISOR_CM3_PER_KG;
  const chargeableKg = Math.max(totalActualKg, volumetricKg);
  return { lines, totalActualKg, totalVolumeCm3, volumetricKg, chargeableKg };
}

// Combines the product-catalog estimate with an optional real outer-
// carton override (actual measured dims + gross weight, once packed —
// always takes precedence when given, per carton, over the catalog
// estimate) into the single shipment-weight description the rest of this
// module (computeChargeableWeightPerParcel, quoteFreight) already
// expects: a total kg figure plus an optional per-parcel dims block.
// cartonOverride: { lengthCm, widthCm, heightCm, grossWeightKg, cartons }
// — any subset may be provided; only fields that are actually set (> 0)
// override their catalog-derived counterpart. Returns
// { totalWeightKg, parcelCount, dims, source: "catalog" | "override" | "mixed",
//   catalog: {...computeOrderWeights result...} }.
function resolveShipmentWeight({ products, quantities, cartonOverride }) {
  const catalog = computeOrderWeights(products || [], quantities || {});
  cartonOverride = cartonOverride || {};
  const cartons = Math.max(1, Number(cartonOverride.cartons) || 1);
  const hasDimsOverride = cartonOverride.lengthCm > 0 && cartonOverride.widthCm > 0 && cartonOverride.heightCm > 0;
  const hasWeightOverride = cartonOverride.grossWeightKg > 0;

  let totalWeightKg;
  let dims = null;
  let source;
  if (hasWeightOverride) {
    totalWeightKg = cartonOverride.grossWeightKg * cartons;
    source = hasDimsOverride ? "override" : "mixed";
  } else {
    totalWeightKg = catalog.chargeableKg;
    source = "catalog";
  }
  if (hasDimsOverride) {
    dims = { length: cartonOverride.lengthCm, width: cartonOverride.widthCm, height: cartonOverride.heightCm, unit: "cm" };
    if (!hasWeightOverride) source = "mixed"; // real dims, but catalog-estimated weight
  }
  return { totalWeightKg, parcelCount: cartons, dims, source, catalog };
}

// ---------- Rate card model ----------
let rateCardSeq = 0;
function newRateCardId() {
  rateCardSeq += 1;
  return `rc_${Date.now().toString(36)}_${rateCardSeq}`;
}

function emptyManualCard(warehouseId, name, weightUnit, dimUnit, currency) {
  return {
    id: newRateCardId(),
    warehouseId,
    name,
    mode: "bracket", // "bracket" | "perUnit"
    weightUnit,
    dimUnit,
    currency: currency || "", // e.g. "USD", "GBP" — shown alongside every price
    zoneSource: "manual", // "manual" | "usps"
    zones: ["All"],
    countryZoneMap: {}, // country name -> zone name; empty = user picks zone directly
    dimDivisor: null,
    // Each row: { min, max, prices } — prices[zone] is normally a flat
    // total price for that weight bracket. A row may instead set
    // `perKg: true`, meaning prices[zone] is a rate PER KG (the bracket's
    // actual/chargeable weight is multiplied in at quote time) rather than
    // a flat total — used for carriers whose rate sheets switch from flat
    // per-bracket pricing to a per-kilogram multiplier above some weight
    // (e.g. FedEx HK's Package tables above 20.5kg). Omit/false = flat
    // total, the historical default.
    brackets: [{ min: 0, max: null, prices: { All: 0 } }],
    perUnit: { All: { base: 0, rate: 0, min: 0 } },
    // A flat fee added to every parcel on top of the bracket/perUnit price —
    // for carrier surcharges that apply to every package regardless of zone
    // or weight (e.g. Royal Mail's "Green Surcharge" + "Peak Season
    // Surcharge" — see UK rate card notes below). Zone- or weight-specific
    // surcharges belong baked into the bracket/perUnit price itself instead
    // (see notes); this is only for the always-on, zone-independent ones.
    flatSurcharge: 0,
    // A proportional surcharge applied to the bracket/perUnit price before
    // flatSurcharge is added — e.g. a carrier's fuel surcharge quoted as a
    // percentage rather than a flat fee (0.03 = 3%). Very common across
    // carriers (GPS's FedEx Ground: "10% off"; NL's Spring/Post NL: 3%;
    // DHL: 1.25%; DPD: 16%) — a single flat-$ field can't represent this.
    percentSurcharge: 0,
    // ISO date strings (or null) — informational, surfaced as a warning by
    // quoteFreight() when the card is past its expiry, but never blocks a
    // quote (an expired rate card is still the best estimate available
    // until a fresh one is entered/imported).
    effectiveDate: null,
    expiryDate: null,
    // Whether a shipment heavier than this card's own top bracket may be
    // proposed as multiple separately-rated consignments (see
    // proposeSplitConsignments()) rather than refused outright. Off by
    // default — splitting isn't always permitted (customs docs for a
    // single international consignment, a carrier that just doesn't offer
    // it), so this is a per-card opt-in, not an assumption.
    splitAllowed: false,
    // The carrier's actual physical parcel/shipment weight limit, if lower
    // than (or just distinct from) the rate table's own top bracket — caps
    // how big any single proposed consignment may be. Null = no separate
    // physical cap known; the rate table's own max bracket is the only
    // limit applied.
    maxPhysicalWeight: null,
    notes: "",
  };
}

function emptyUspsCard(warehouseId, name, weightUnit, dimUnit, currency) {
  const zones = ["1", "2", "3", "4", "5", "6", "7", "8", "9"];
  const zeros = Object.fromEntries(zones.map((z) => [z, 0]));
  return {
    id: newRateCardId(),
    warehouseId,
    name,
    mode: "bracket",
    weightUnit,
    dimUnit,
    currency: currency || "",
    zoneSource: "usps",
    zones,
    countryZoneMap: {},
    dimDivisor: null,
    // Same { min, max, prices } bracket-row shape as emptyManualCard()
    // above, including the optional perKg: true flag (see there for docs).
    brackets: [{ min: 0, max: 1, prices: { ...zeros } }],
    perUnit: Object.fromEntries(zones.map((z) => [z, { base: 0, rate: 0, min: 0 }])),
    flatSurcharge: 0,
    percentSurcharge: 0,
    effectiveDate: null,
    expiryDate: null,
    splitAllowed: false,
    maxPhysicalWeight: null,
    notes: "",
  };
}

// ---------- HK (OPS-WH01) — real rate cards ----------
// Source: "Courtesy-Net-Rates15788832-English.PDF.PDF" ("Courtesy Net Rates"),
// Agreement No.: 6688416-119 / Proposal No.: 15788832, Net rates effective
// as of 09 February 2026, applicable for location HKG only. Covers FedEx
// International Export "Package" service rates only — IPE (Priority
// Express), IP (Priority), IE (Economy) — parsed from the rate sheet's
// per-service Package weight-break tables (pp. 4-6 IPE, 7-9 IP, 10-12 IE)
// and the Export Zone Chart (pp. 20-24, IE/IP/IPE columns respectively —
// each service gets its own country->zone map since a handful of
// countries aren't served by every service, esp. IE).
//
// Envelope and Pak sub-tables (FedEx-branded packaging tiers, not real
// customer cartons) are deliberately excluded — only the "Package" block
// is modeled. Each Package table is 41 flat-price weight brackets
// (0.5-20.5kg in 0.5kg steps) followed by per-kilogram tiered bands above
// that (the rate sheet: "Per-kilogram rates. Multiply by actual shipment
// weight in kilogram to get the net rate.") — see the priceForZone()
// `perKg` bracket flag added below to support this. IE's per-kg tier is
// unusual: it splits the >1,000kg band into two (1,000-9,999kg and
// 10,000-99,999kg, the latter priced HIGHER per-kg) where IPE/IP use one
// unified 1,000-99,999kg band — modeled faithfully rather than assumed
// uniform across services. Per-kg bracket rows continue seamlessly
// (min = prior bracket's max + 0.01) from the last 0.5kg flat bracket, so
// there's no coverage gap even though the sheet's own printed range label
// for the first per-kg band starts at "21.0" (not "20.51") — a
// presentation-only rounding in the source, not a real pricing gap.
//
// dimDivisor 5000 is FedEx's own volumetric divisor (L x W x H / 5,000 for
// cm, per "FedEx Surcharges (2026) - English.pdf"). splitAllowed is false
// and maxPhysicalWeight is null — the top per-kg band already covers up to
// 99,999kg, so there's no realistic case of exceeding this card's own
// table.
//
// NOT included in these prices (add manually at quote time):
//   - Fuel Surcharge — a floating weekly % of the US Gulf Coast Jet Fuel
//     Index, published at fedex.com/en-hk/shipping/surcharges.
//   - Additional Handling Surcharge — triggers on longest side >121cm,
//     2nd-longest side >76cm, cubic volume >169,901cm³, or actual weight
//     >25kg (per the companion Surcharges PDF).
//   - Oversize Surcharge — triggers on longest side >243cm, actual weight
//     >50kg, or cubic volume >283,168cm³.
//   - Unauthorized Package Surcharge (non-conforming packaging).
//
// ⚠ The source rate sheet itself displayed account status 'Delete' as of
// its generation date (09-Feb-2026); the user has since confirmed with
// FedEx/finance that the account is active — kept here as provenance
// history, not a live caveat.
//
// Net rates are not legally binding per the source document — the actual
// invoiced amount always prevails. Do not hand-edit the data blocks below
// — regenerate from the source PDF (see webapp/tests/test_task_g.js for
// the spot-check values used to validate the parse) if the rate sheet is
