// Yodel (new this version — 2026-09-21 rate sheet; the tab existed before
// but wasn't in use). Two zones (Mainland / Remote Areas); named weight
// tiers (Small/Medium/Large) treated as an ascending, non-overlapping
// bracket ladder — a shipment is priced at the cheapest tier that covers
// its weight, same convention as every other UK card here. 24H service
// has no Small tier and isn't offered to Zone B at all (source shows
// "/") — left unpriced there rather than guessed at. >30kg isn't
// accepted by Yodel at all.
function ukYodel48hCard() {
  const card = emptyManualCard("UK", "Yodel 48H", "kg", "cm", "GBP");
  card.zones = ["Zone A", "Zone B"];
  card.brackets = [
    { min: 0, max: 3, prices: { "Zone A": 2.7, "Zone B": 7.3 } }, // Small (YDL_SP48)
    { min: 3.01, max: 17, prices: { "Zone A": 4.2, "Zone B": 9.45 } }, // Medium (YDL_MP48)
    { min: 17.01, max: 30, prices: { "Zone A": 5.45, "Zone B": 9.45 } }, // Large (YDL_LP48)
  ];
  card.percentSurcharge = 0.032; // real 3.2% fuel surcharge, every package (unlike RM/DPD/Evri, not included in the base rate)
  // Yodel explicitly states packages over 30kg are refused outright (not
  // just surcharged) — so a heavier order genuinely needs splitting into
  // multiple real ≤30kg parcels, not a single oversized one.
  card.splitAllowed = true;
  card.maxPhysicalWeight = 30;
  card.notes =
    "Zone A = UK Mainland. Zone B = Remote Areas (see Yodel's published remote-area postcode list). Packages " +
    "over 30kg are not accepted — a heavier shipment is priced here as a split into multiple sub-30kg " +
    "parcels; confirm actual packing before quoting. Other surcharges not included (quote separately if " +
    "applicable): Overweight " +
    "Surcharge (£3.50-£80/package, tiered by how far over the tier's weight limit), Oversize Surcharges " +
    "(£3.50-£80/package, tiered by dims/volume), London Congestion Fee (£1.50/package), Return Shipping Fee " +
    "(= outbound rate), Non-machinable Parcel Fee (£5/package), Relabelling (£0.50/package), Dimension " +
    "Discrepancy Fee (£2/package), delivery interception (£5/shipment if successful). BFPO/FBA not supported. " +
    "Claims: £5/claim, investigation must start within 14 days and formal claim submitted within 28 days of " +
    "delivery; compensation for loss capped at £25/package, subject to Yodel's final decision.";
  return card;
}
function ukYodel24hCard() {
  const card = emptyManualCard("UK", "Yodel 24H", "kg", "cm", "GBP");
  card.zones = ["Zone A", "Zone B"];
  card.brackets = [
    { min: 0, max: 17, prices: { "Zone A": 5, "Zone B": null } }, // Medium (YDL_MP24) — not offered to Zone B
    { min: 17.01, max: 30, prices: { "Zone A": 6, "Zone B": null } }, // Large (YDL_LP24) — not offered to Zone B
  ];
  card.percentSurcharge = 0.032; // see ukYodel48hCard() above
  card.splitAllowed = true; // see ukYodel48hCard() above — same 30kg refusal threshold
  card.maxPhysicalWeight = 30;
  card.notes = "24H service has no Small-parcel tier and isn't offered to Zone B (remote areas) at all — use " +
    "Yodel 48H for those. " + ukYodel48hCard().notes;
  return card;
}

// ---------- Import: "US-to-Global eCom Parcel Rate" style sheets ----------
// Some rate cards (e.g. GPS/USOPS-WH04's international parcel rates) are
// far too large to hand-type or bake into source — tens of destination
// countries x 60+ weight-break rows. Rather than embed that as static
// data (which also can't be refreshed when the carrier reissues rates),
// this parses the sheet's own layout at import time: a "Destinations" row
// of country names, a "Terms" row (DDP/DDU), a "Dim Factor" row, a
// "Minimum" row, "Effective Date:"/"Expired Date:" rows, then one row per
// weight break point (lb) with a price per country column. Returns
// { card } or { error }. rawRows: raw 2D array, e.g. from
// io.sheetToRawRows(wb, sheetName, null).
function excelSerialToIsoDate(serial) {
  if (serial instanceof Date) return isNaN(serial.getTime()) ? null : serial.toISOString().slice(0, 10);
  if (typeof serial !== "number" || !isFinite(serial)) return null;
  return new Date(Date.UTC(1899, 11, 30) + serial * 86400000).toISOString().slice(0, 10);
}

function parseUsToGlobalRateSheet(rawRows, opts) {
  opts = opts || {};
  const firstCell = (row) => (row && row[0] != null ? String(row[0]).trim() : "");

  const destRowIdx = rawRows.findIndex((r) => /^destinations?$/i.test(firstCell(r)));
  if (destRowIdx < 0) {
    return { error: 'Could not find a "Destinations" row in column A — this doesn\'t look like a US-to-Global rate sheet.' };
  }
  const destRow = rawRows[destRowIdx];
  const zoneCols = [];
  for (let c = 1; c < destRow.length; c++) {
    const name = destRow[c] == null ? "" : String(destRow[c]).trim();
    if (name) zoneCols.push({ col: c, name });
  }
  if (!zoneCols.length) return { error: 'Found a "Destinations" row but no destination names in it.' };

  const termsRowIdx = rawRows.findIndex((r) => /^terms$/i.test(firstCell(r)));
  let terms = "";
  if (termsRowIdx >= 0) {
    const termsRow = rawRows[termsRowIdx];
    const found = zoneCols.map((z) => termsRow[z.col]).find((v) => v != null && String(v).trim());
    terms = found ? String(found).trim() : "";
  }

  const dimRowIdx = rawRows.findIndex((r) => /^dim\s*factor$/i.test(firstCell(r)));
  let dimDivisor = null;
  if (dimRowIdx >= 0) {
    const dimRow = rawRows[dimRowIdx];
    const found = zoneCols.map((z) => dimRow[z.col]).find((v) => typeof v === "number" && v > 0);
    if (found) dimDivisor = found;
  }

  // "Currency:" is labelled in column A with the code in some later column
  // on the same row (position varies, like the date rows) — take the first
  // non-empty cell after column A.
  const currencyRow = rawRows.find((r) => firstCell(r).toLowerCase().indexOf("currency") === 0);
  let currency = "";
  if (currencyRow) {
    const found = currencyRow.slice(1).find((v) => v != null && String(v).trim());
    currency = found ? String(found).trim() : "";
  }

  const minRowIdx = rawRows.findIndex((r) => /^minimum$/i.test(firstCell(r)));
  let hasNonzeroMinimum = false;
  if (minRowIdx >= 0) {
    const minRow = rawRows[minRowIdx];
    hasNonzeroMinimum = zoneCols.some((z) => Number(minRow[z.col]) > 0);
  }

  // Date rows are labelled in column A but the serial/Date value's column
  // isn't consistent between sheets — scan the whole row for the first
  // plausible value instead of assuming a fixed column.
  const findDateRow = (label) => rawRows.find((r) => firstCell(r).toLowerCase().indexOf(label) === 0);
  const extractDateValue = (row) => (row || []).find((v) => v instanceof Date || (typeof v === "number" && v > 30000 && v < 80000));
  const effectiveDate = excelSerialToIsoDate(extractDateValue(findDateRow("effective date")));
  const expiredRow = findDateRow("expired date") || findDateRow("expiry date");
  const expiryDate = excelSerialToIsoDate(extractDateValue(expiredRow));

  // Weight break points (lb) start right after the "...Transit Time"
  // header row (falls back to right after the Minimum row if that header
  // isn't found), and run while column A keeps parsing as a positive
  // number — the first non-numeric/blank row ends the table.
  const headerRowIdx = rawRows.findIndex((r) => /transit/i.test(firstCell(r)));
  const startIdx = headerRowIdx >= 0 ? headerRowIdx + 1 : (minRowIdx >= 0 ? minRowIdx + 1 : destRowIdx + 1);
  const brackets = [];
  let prevMax = 0;
  for (let r = startIdx; r < rawRows.length; r++) {
    const weight = parseFloat(firstCell(rawRows[r]));
    if (!(weight > 0)) break;
    const row = rawRows[r];
    const prices = {};
    for (const z of zoneCols) {
      const v = row[z.col];
      // A blank/"-" cell means that destination has no rate at this weight
      // (not a $0 rate) — null, so priceForZone reports it rather than
      // silently quoting free shipping.
      prices[z.name] = typeof v === "number" ? Math.round(v * 100) / 100 : (parseFloat(v) || null);
    }
    const min = brackets.length ? Math.round((prevMax + 0.01) * 100) / 100 : 0;
    brackets.push({ min, max: weight, prices });
    prevMax = weight;
  }
  if (!brackets.length) {
    return { error: "Found destination columns but no weight-break rows with prices under them — check the sheet layout." };
  }

  const card = emptyManualCard(
    opts.warehouseId || "US_GPS",
    opts.cardName || `US to Global${terms ? ` (${terms})` : ""}`,
    opts.weightUnit || "lb",
    opts.dimUnit || "in",
    currency || opts.currency || ""
  );
  card.zones = zoneCols.map((z) => z.name);
  card.countryZoneMap = Object.fromEntries(card.zones.map((n) => [n, n]));
  card.brackets = brackets;
  card.dimDivisor = dimDivisor;
  card.effectiveDate = effectiveDate;
  card.expiryDate = expiryDate;
  const notes = [];
  if (terms) notes.push(`Terms: ${terms}.`);
  if (effectiveDate || expiryDate) notes.push(`Effective ${effectiveDate || "?"} to ${expiryDate || "?"} per source file.`);
  if (hasNonzeroMinimum) {
    notes.push('This sheet has a non-zero per-destination "Minimum" charge that this tool does not yet apply automatically — check the Minimum row in the source file.');
  }
  card.notes = notes.join(" ");
  return { card };
}

// ---------- Import: "US domestic zone" rate sheets (Zone N columns x lb/oz weight rows) ----------
// The shape used by GPS's own USPS/UPS Ground/FedEx Ground domestic
// sheets, and Stord's own multi-service "RATE CARD" sheet: a header row
// ("Rate Category", "Lbs.", "Ounces (OZ)", etc.) followed by zone columns
// — "Zone N", a bare zone number, a named zone (e.g. Stord's "Hawaii",
// "Alaska Metro"), or even a country name for a card whose "zones" are
// really destination countries (e.g. Stord's own "Priority DDP" block) —
// then weight-indexed rows of flat prices. Some sheets put the weight
// unit label on the row ABOVE the actual zone header (paired with a
// "ZONES" sub-label) instead of on the header row itself — both shapes
// are handled. Some sheets (USPS Ground Advantage) carry TWO such blocks
// in one tab — an oz-indexed table for <1lb, then an lb-indexed table —
// both reusing the same zone columns; both are parsed and stitched into
// one continuous bracket ladder (oz converted to lb). A sheet with a
// second block of columns after a gap (e.g. a Commercial | Residential
// side-by-side layout) only has the first block parsed — B2B quoting
// wants commercial rates, and the gap column is what stops the scan.
//
// A single sheet can also hold multiple named services one after another
// (Stord's "RATE CARD" sheet: "ECONOMY", "GROUND STANDARD COMMERCIAL",
// "OVERNIGHT", ... each its own standalone section-title row, own header,
// own weight-bracket table) — pass opts.sectionLabel to parse just one
// named section rather than every header block in the sheet.
//
// opts.buildCountryZoneMap: true builds an identity country -> zone map
// (for a country-named-zones block like Priority DDP) so the destination
// picker offers a country dropdown, not just a bare zone dropdown.
//
// Returns { card } or { error }.
function parseUsDomesticZoneSheet(rawRows, opts) {
  opts = opts || {};
  const firstCell = (row) => (row && row[0] != null ? String(row[0]).trim() : "");
  // Used to recognize a ROW as a header-row candidate (checked against
  // column A only) — deliberately broader than CELL_REJECT_RE below.
  const ROW_HEADER_RE = /^(rate categor|lbs\.?|weight|ounces|pounds|zone|country code)/i;
  // Used inside zoneHeaderCellName to reject a stray second "Lbs."/
  // "Weight..." header value appearing as a COLUMN value (the Commercial |
  // Residential gap stopper) — deliberately narrower than ROW_HEADER_RE:
  // it must NOT reject a "Zone N" column value, which is a valid zone name.
  const CELL_REJECT_RE = /^(rate categor|lbs\.?|weight|ounces|pounds)/i;

  function zoneHeaderCellName(v) {
    if (v == null) return null;
    const s = String(v).trim();
    if (s === "" || CELL_REJECT_RE.test(s) || /^zones?$/i.test(s)) return null;
    const m = /^zone\s*(\d+)$/i.exec(s);
    return m ? m[1] : s; // "Zone N" -> N; otherwise the label itself (bare number, named zone, or country)
  }

  // Track the most recent standalone one-cell "section title" row (e.g.
  // "ECONOMY") so header blocks can be filtered to one named section.
  let currentSection = null;
  const headerRows = [];
  for (let r = 0; r < rawRows.length; r++) {
    const row = rawRows[r];
    if (!row) continue;
    const label = firstCell(row);
    const hasOnlyCol0 = label !== "" && row.slice(1).every((v) => v == null || String(v).trim() === "");
    if (hasOnlyCol0 && !ROW_HEADER_RE.test(label)) { currentSection = label; continue; }
    if (label !== "" && !ROW_HEADER_RE.test(label)) continue; // some other non-header text row

    const zones = [];
    for (let c = 1; c < row.length; c++) {
      const name = zoneHeaderCellName(row[c]);
      if (name == null) {
        if (zones.length) break; // gap after zone columns started -> stop (skips Residential/notes blocks)
        continue; // gap before any zone column seen yet -> keep scanning
      }
      zones.push({ col: c, name });
    }
    if (zones.length < 2) continue;
    // Some sheets put the weight-unit label on this row (label !== ""); others
    // put it on the row above, paired with a "ZONES" sub-label there instead.
    const effectiveLabel = label || firstCell(rawRows[r - 1]);
    headerRows.push({ row: r, label: effectiveLabel, zones, section: currentSection });
  }

  // Some sheets carry a "pretty name" row that introduces no weight data
  // of its own (e.g. Stord's Priority DDP: a row of full country names
  // directly above a row of "Ounces (OZ)" + 2-letter country codes in the
  // very same columns) — that name row would otherwise be mistaken for
  // its own header block. Detect any such row (no parseable weight on the
  // very next line) and use it as a column -> display-name overlay for
  // the rest of its section (there can be more than one real header block
  // per section — e.g. an oz table then a lb table further down, both
  // reusing the same code columns — so this isn't just "the row right
  // above", it's shared across the whole section), instead of a block.
  const nameOverlayBySection = new Map();
  for (let i = headerRows.length - 1; i >= 0; i--) {
    const hr = headerRows[i];
    const nextRow = rawRows[hr.row + 1];
    const introducesData = nextRow && parseFloat(firstCell(nextRow)) > 0;
    if (introducesData) continue;
    if (!nameOverlayBySection.has(hr.section)) nameOverlayBySection.set(hr.section, new Map());
    const overlay = nameOverlayBySection.get(hr.section);
    for (const z of hr.zones) if (!overlay.has(z.col)) overlay.set(z.col, z.name);
    headerRows.splice(i, 1);
  }
  for (const hr of headerRows) {
    const overlay = nameOverlayBySection.get(hr.section);
    if (!overlay) continue;
    hr.zones = hr.zones.map((z) => ({ col: z.col, name: overlay.get(z.col) || z.name }));
  }

  const relevant = opts.sectionLabel
    ? headerRows.filter((hr) => hr.section && hr.section.trim().toLowerCase() === opts.sectionLabel.trim().toLowerCase())
    : headerRows;
  if (!relevant.length) {
    return opts.sectionLabel
      ? { error: `Could not find a section titled "${opts.sectionLabel}" with a weight × zone table under it.` }
      : { error: 'Could not find a weight × zone header row (e.g. "Rate Category", "Lbs.") — this doesn\'t look like a US domestic zone rate sheet.' };
  }

  const zoneNamesInOrder = [];
  for (const hr of relevant) for (const z of hr.zones) if (!zoneNamesInOrder.includes(z.name)) zoneNamesInOrder.push(z.name);

  const brackets = [];
  let prevMaxLb = 0;
  for (const hr of relevant) {
    const isOz = /\boz\b|ounces/i.test(hr.label);
    for (let r = hr.row + 1; r < rawRows.length; r++) {
      const row = rawRows[r];
      const w = parseFloat(firstCell(row));
      if (!(w > 0)) break; // blank row, "Oversized" label, or the next header block ends this one
      const weightLb = isOz ? w / 16 : w;
      const prices = {};
      for (const z of hr.zones) {
        const v = row[z.col];
        prices[z.name] = typeof v === "number" ? Math.round(v * 100) / 100 : (parseFloat(v) || null);
      }
      const min = brackets.length ? Math.round((prevMaxLb + 0.0001) * 10000) / 10000 : 0;
      brackets.push({ min, max: Math.round(weightLb * 10000) / 10000, prices });
      prevMaxLb = weightLb;
    }
  }
  if (!brackets.length) {
    return { error: "Found a weight × zone header row but no weight rows with prices under it." };
  }

  const card = emptyManualCard(
    opts.warehouseId || "US_GPS",
    opts.cardName || opts.sectionLabel || "US domestic rate sheet",
    "lb",
    "in",
    opts.currency || "USD"
  );
  card.zones = zoneNamesInOrder;
  if (opts.buildCountryZoneMap) card.countryZoneMap = Object.fromEntries(zoneNamesInOrder.map((n) => [n, n]));
  card.brackets = brackets;
  card.dimDivisor = opts.dimDivisor || null;
  card.notes = opts.notes || "";
  return { card };
}

// ---------- Import: UPS-style "zone code" international sheets ----------
// UPS's own international rate sheets don't key prices by country
// directly — a "Zones" header row lists UPS's internal numeric zone
// codes, and a separate "Export Zones" tab maps each destination country
// to one of those codes (differently depending on which US region the
// shipment originates from — this file has both a "Western U.S." and an
// "Eastern U.S." column; pass opts.origin: "western" | "eastern", default
// "eastern"). Weight rows beyond the flat-price table switch to a
// "Per Lb" formula row instead of a bracket (e.g. >150lb) — that tier
// isn't modeled here (bracket pricing only), and is called out in notes
// rather than silently dropped. Returns { card } or { error }.
function parseUpsWorldwideExpeditedSheets(rateRawRows, exportZonesRawRows, opts) {
  opts = opts || {};
  const origin = opts.origin === "western" ? "western" : "eastern";
  const firstCell = (row) => (row && row[0] != null ? String(row[0]).trim() : "");

  const zoneHeaderIdx = rateRawRows.findIndex((r) => /^zones$/i.test(firstCell(r)));
  if (zoneHeaderIdx < 0) return { error: 'Could not find a "Zones" header row in the rate sheet.' };
  const zoneHeaderRow = rateRawRows[zoneHeaderIdx];
  const zoneCols = [];
  for (let c = 3; c < zoneHeaderRow.length; c++) {
    const v = zoneHeaderRow[c];
    if (v == null || String(v).trim() === "") continue;
    zoneCols.push({ col: c, name: String(v).trim() });
  }
  if (!zoneCols.length) return { error: "Found a Zones header row but no zone codes in it." };

  const brackets = [];
  let prevMax = 0;
  let perLbNote = "";
  for (let r = zoneHeaderIdx + 1; r < rateRawRows.length; r++) {
    const row = rateRawRows[r];
    if (!row) continue;
    const rateType = row[1] == null ? "" : String(row[1]).trim();
    const weight = parseFloat(row[2]);
    if (!(weight > 0)) continue;
    if (/per\s*lb/i.test(rateType)) {
      perLbNote = `Weights above ${prevMax}lb price per additional lb on the source sheet — not modeled here (bracket pricing only); quote those manually.`;
      break;
    }
    const prices = {};
    for (const z of zoneCols) {
      const v = row[z.col];
      prices[z.name] = typeof v === "number" ? Math.round(v * 100) / 100 : (parseFloat(v) || null);
    }
    const min = brackets.length ? Math.round((prevMax + 0.01) * 100) / 100 : 0;
    brackets.push({ min, max: weight, prices });
    prevMax = weight;
  }
  if (!brackets.length) return { error: "Found zone columns but no weight-bracket rows under them." };

  const originColIdx = origin === "western" ? 1 : 2;
  const countryZoneMap = {};
  for (const row of exportZonesRawRows) {
    if (!row || row[0] == null) continue;
    const raw = String(row[0]).trim();
    const m = /^(.*?)\s*\/\s*[A-Za-z]{2,3}$/.exec(raw);
    const country = (m ? m[1] : raw).trim();
    // The sheet's own header rows ("Country", "Originating from", "Western
    // U.S.", ...) parse as non-numeric "zone codes" — skip anything that
    // isn't actually a numeric UPS zone code, rather than trust row position.
    const zoneCode = row[originColIdx];
    if (!country || zoneCode == null || zoneCode === "" || !/^\d+$/.test(String(zoneCode).trim())) continue;
    countryZoneMap[country] = String(zoneCode).trim();
  }
  // A few high-volume destinations (e.g. Canada) are called out directly in
  // the rate sheet's own "Destination" row (right under the "Zones" header)
  // rather than via the Export Zones lookup — pick those up too. Where the
  // same country label appears under more than one zone column (Canada
  // does: 71 and 72), only the first is mapped automatically; the other
  // zone stays reachable via the zone dropdown directly.
  const destinationRow = rateRawRows[zoneHeaderIdx + 1];
  if (destinationRow && /^destination$/i.test(firstCell(destinationRow))) {
    for (const z of zoneCols) {
      const label = destinationRow[z.col] == null ? "" : String(destinationRow[z.col]).trim();
      if (label && !countryZoneMap[label]) countryZoneMap[label] = z.name;
    }
  }
  if (!Object.keys(countryZoneMap).length) return { error: "Could not build a country → zone map from the Export Zones sheet." };

  const card = emptyManualCard(
    opts.warehouseId || "US_GPS",
    opts.cardName || `UPS Worldwide Expedited (${origin === "western" ? "Western" : "Eastern"} US origin)`,
    "lb",
    "in",
    opts.currency || "USD"
  );
  card.zones = zoneCols.map((z) => z.name);
  card.countryZoneMap = countryZoneMap;
  card.brackets = brackets;
  card.dimDivisor = opts.dimDivisor || null;
  const notes = [`Zone codes are UPS's own, origin: ${origin === "western" ? "Western" : "Eastern"} U.S. (${Object.keys(countryZoneMap).length} destination countries mapped from the Export Zones sheet).`];
  if (perLbNote) notes.push(perLbNote);
  card.notes = notes.join(" ");
  return { card };
}


// ---------- Import: EU intra-region "destination rows x weight columns" sheets ----------
// The shape used by Stord's EU-origin intra-EU rate card: unlike the
// other two parsers, DESTINATION is a row label here and WEIGHT is the
// column axis (columns like "0.25kg", "0.5kg", ...), and each destination
// can appear on MULTIPLE rows — one per carrier option (e.g. Austria via
// "SPRING_POST NL" and again via "DHL_DE: WP", at different prices). A
// sheet can also have more than one such block (e.g. a main EU block, then
// a "DESTINATION (MIDDLE EAST)" block further down) — all are scanned.
// Returns { cards: [...] } (one per distinct carrier — the natural service
// split, same idea as ukRoyalMailCard()/ukDpdUkCard() being separate
// cards) or { error }. Blank/"-" cells mean "not offered at that
// weight/destination", not a $0 price — parsed as null so priceForZone()
// reports it correctly instead of quoting free shipping.
function parseEuIntraDestinationRowsSheet(rawRows, opts) {
  opts = opts || {};
  const firstCell = (row) => (row && row[0] != null ? String(row[0]).trim() : "");
  const cellAt = (row, c) => (row && row[c] != null ? String(row[c]).trim() : "");

  const headerIdxs = [];
  for (let r = 0; r < rawRows.length; r++) {
    if (/^destination\b/i.test(firstCell(rawRows[r]))) headerIdxs.push(r);
  }
  if (!headerIdxs.length) {
    return { error: 'Could not find a "DESTINATION" header row — this doesn\'t look like this shape.' };
  }

  // byCarrier: carrier name -> { rows: [{destination, prices: {kg: value}}], fuelPct }
  const byCarrier = new Map();
  for (const headerIdx of headerIdxs) {
    const headerRow = rawRows[headerIdx];
    const carrierCol = headerRow.findIndex((v) => v != null && /^carrier$/i.test(String(v).trim()));
    const fuelCol = headerRow.findIndex((v) => v != null && /^fuel surcharge/i.test(String(v).trim()));
    const weightCols = [];
    for (let c = 0; c < headerRow.length; c++) {
      const v = headerRow[c];
      if (v == null) continue;
      const m = /^([\d.]+)\s*kg$/i.exec(String(v).trim());
      if (m) weightCols.push({ col: c, kg: parseFloat(m[1]) });
    }
    if (!weightCols.length) continue; // a header-like row with no weight columns isn't a real block

    for (let r = headerIdx + 1; r < rawRows.length; r++) {
      const row = rawRows[r];
      const destination = firstCell(row);
      // A blank destination cell does NOT reliably end a block — some
      // sheets have a blank spacer row (or footnote rows with no weight
      // data, caught by hasAnyWeightData below) in the middle of a single
      // logical block. Only a genuinely new header row ends this scan.
      if (!destination) continue;
      if (/^destination\b/i.test(destination)) break; // the next header block starts here

      const hasAnyWeightData = weightCols.some((wc) => row[wc.col] != null && String(row[wc.col]).trim() !== "");
      if (!hasAnyWeightData) continue; // a legend/footnote row sharing column A, e.g. "DHL_DE : PI" = "Pakket International"

      const carrier = carrierCol >= 0 && cellAt(row, carrierCol) ? cellAt(row, carrierCol) : "Default";
      const fuelRaw = fuelCol >= 0 ? row[fuelCol] : null;
      const fuelPct = typeof fuelRaw === "number" ? fuelRaw : null;

      if (!byCarrier.has(carrier)) byCarrier.set(carrier, { rows: [], fuelPcts: [] });
      const entry = byCarrier.get(carrier);
      const prices = {};
      for (const wc of weightCols) {
        const v = row[wc.col];
        prices[wc.kg] = typeof v === "number" ? Math.round(v * 100) / 100 : null; // "-" or blank -> null, not 0
      }
      entry.rows.push({ destination, prices });
      if (fuelPct != null) entry.fuelPcts.push(fuelPct);
    }
  }
  if (!byCarrier.size) return { error: "Found DESTINATION header row(s) but no destination rows with weight data under them." };

  const cards = [];
  for (const [carrier, entry] of byCarrier) {
    const zones = [];
    for (const r of entry.rows) if (!zones.includes(r.destination)) zones.push(r.destination);
    const allKg = [...new Set(entry.rows.flatMap((r) => Object.keys(r.prices).map(Number)))].sort((a, b) => a - b);
    const brackets = [];
    let prevMax = 0;
    for (const kg of allKg) {
      const prices = {};
      for (const r of entry.rows) prices[r.destination] = r.prices[kg];
      const min = brackets.length ? Math.round((prevMax + 0.01) * 100) / 100 : 0;
      brackets.push({ min, max: kg, prices });
      prevMax = kg;
    }
    // Fuel % is a carrier-level fee, not per-destination — take the first
    // numeric value seen (a handful of rows carry a stray text value like
    // "3% Included" instead of the number; those are simply skipped).
    const fuelPct = entry.fuelPcts.length ? entry.fuelPcts[0] : 0;

    const card = emptyManualCard(
      opts.warehouseId || "NL",
      opts.cardNamePrefix ? `${opts.cardNamePrefix} — ${carrier}` : carrier,
      "kg", "cm",
      opts.currency || "EUR"
    );
    card.zones = zones;
    card.countryZoneMap = Object.fromEntries(zones.map((z) => [z, z]));
    card.brackets = brackets;
    card.dimDivisor = opts.dimDivisor || null;
    card.percentSurcharge = fuelPct;
    const notes = [];
    if (fuelPct) notes.push(`Fuel surcharge excluded from these prices per the source file — applied here as a ${(fuelPct * 100).toFixed(2)}% surcharge on top of the base rate.`);
    if (opts.extraNotes) notes.push(opts.extraNotes);
    card.notes = notes.join(" ");
    cards.push(card);
  }
  return { cards };
}

