// Stord's OVERVIEW tab states the $3.00/lb-over-max, $50-minimum
// overage rule generically for "any shipment that exceeds the maximum
// weight listed on the rate card" (not just Priority DDP/International
// DDU, which happen to also repeat it in their own per-card notes) — it
// applies to every Stord rate card, including these 3, per that shared
// statement. Same mechanism as stordPriorityDdpAtlCard() above.
function stordStandardDdpAtlCard() {
  const card = emptyManualCard("US_STORD_ATL", "Stord Standard DDP (International)", "lb", "in");
  Object.assign(card, STORD_STANDARD_DDP_SEED, { id: card.id, name: card.name, warehouseId: card.warehouseId });
  card.overageRatePerUnit = 3.0;
  card.overageMinCharge = 50;
  return card;
}
function stordStandardDdpRnoCard() {
  const card = emptyManualCard("US_STORD_RNO", "Stord Standard DDP (International)", "lb", "in");
  Object.assign(card, STORD_STANDARD_DDP_SEED, { id: card.id, name: card.name, warehouseId: card.warehouseId });
  card.overageRatePerUnit = 3.0;
  card.overageMinCharge = 50;
  return card;
}
